using Microsoft.EntityFrameworkCore;
using Microsoft.OpenApi.Models;
using RaceDay.Api;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<RaceDayDbContext>(o => o.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection")));
builder.Services.AddDistributedMemoryCache();
builder.Services.AddSession(o => { o.Cookie.HttpOnly = true; o.Cookie.IsEssential = true; o.IdleTimeout = TimeSpan.FromHours(2); });
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(c => { c.SwaggerDoc("v1", new OpenApiInfo { Title = "RaceDay API", Version = "v1", Description = "RaceDay event and enrolment API. Sign in using /api/auth/login; session cookie is used for protected routes." }); });
var app = builder.Build();
app.UseSession();
if (app.Environment.IsDevelopment()) { app.UseSwagger(); app.UseSwaggerUI(); }
app.MapGet("/", () => Results.Ok(new { name = "RaceDay API", swagger = "/swagger" }));
app.MapPost("/api/auth/register", async (RegisterRequest req, RaceDayDbContext db) => {
    if (string.IsNullOrWhiteSpace(req.FullName) || string.IsNullOrWhiteSpace(req.Email) || req.Password.Length < 8) return Results.BadRequest(new { message = "Full name/email required and password must be at least 8 characters." });
    var role = req.Role?.Trim(); if (role is not ("Organiser" or "Participant")) return Results.BadRequest(new { message = "Role must be Organiser or Participant." });
    var email = req.Email.Trim().ToLowerInvariant(); if (await db.Users.AnyAsync(u => u.Email == email)) return Results.Conflict(new { message = "Email already registered." });
    var user = new UserAccount { FullName = req.FullName.Trim(), Email = email, PasswordHash = PasswordSecurity.HashVersioned(req.Password), Role = role, Phone = req.Phone }; db.Users.Add(user); await db.SaveChangesAsync(); return Results.Created($"/api/users/me", new { user.Id, user.FullName, user.Email, user.Role });
}).WithTags("Authentication").WithSummary("Register an organiser or participant");
app.MapPost("/api/auth/login", async (LoginRequest req, HttpContext ctx, RaceDayDbContext db) => {
    var email = req.Email.Trim().ToLowerInvariant(); var user = await db.Users.SingleOrDefaultAsync(u => u.Email == email);
    if (user is null || !PasswordSecurity.VerifyVersioned(req.Password, user.PasswordHash)) return Results.Unauthorized();
    ctx.Session.SetInt32("UserId", user.Id); ctx.Session.SetString("Role", user.Role); ctx.Session.SetString("Name", user.FullName);
    return Results.Ok(new { user.Id, user.FullName, user.Email, user.Role, message = "Login successful. Session cookie set." });
}).WithTags("Authentication").WithSummary("Log in and create a server-side session");
app.MapPost("/api/auth/logout", (HttpContext ctx) => { ctx.Session.Clear(); return Results.Ok(new { message = "Logged out." }); }).WithTags("Authentication");
app.MapGet("/api/users/me", async (HttpContext ctx, RaceDayDbContext db) => { var id = ctx.Session.GetInt32("UserId"); if (id is null) return Results.Unauthorized(); var u = await db.Users.FindAsync(id.Value); return u is null ? Results.NotFound() : Results.Ok(new { u.Id, u.FullName, u.Email, u.Role, u.Phone }); }).WithTags("Users");
app.MapPut("/api/users/me", async (HttpContext ctx, UserUpdate req, RaceDayDbContext db) => { var id = ctx.Session.GetInt32("UserId"); if (id is null) return Results.Unauthorized(); var u = await db.Users.FindAsync(id.Value); if (u is null) return Results.NotFound(); if (string.IsNullOrWhiteSpace(req.FullName)) return Results.BadRequest(new { message = "Full name is required." }); u.FullName = req.FullName.Trim(); u.Phone = req.Phone; await db.SaveChangesAsync(); return Results.Ok(new { u.Id, u.FullName, u.Email, u.Role, u.Phone }); }).WithTags("Users");
app.MapGet("/api/events", async (RaceDayDbContext db) => Results.Ok(await db.Events.Include(e => e.EventType).Select(e => new { e.Id, e.Name, e.Description, e.EventDate, e.Location, e.DistanceKm, EventType = e.EventType!.Name, e.OrganiserId }).ToListAsync())).WithTags("Events");
app.MapGet("/api/events/{id:int}", async (int id, RaceDayDbContext db) => { var e = await db.Events.Include(x => x.EventType).Where(x => x.Id == id).Select(x => new { x.Id, x.Name, x.Description, x.EventDate, x.Location, x.DistanceKm, EventType = x.EventType!.Name, x.OrganiserId }).SingleOrDefaultAsync(); return e is null ? Results.NotFound() : Results.Ok(e); }).WithTags("Events");
app.MapPost("/api/events", async (HttpContext ctx, EventRequest req, RaceDayDbContext db) => { if (!Role(ctx, "Organiser")) return Denied(ctx); if (req.DistanceKm <= 0 || string.IsNullOrWhiteSpace(req.Name) || string.IsNullOrWhiteSpace(req.Location)) return Results.BadRequest(new { message = "Name, location and positive distance are required." }); if (!await db.EventTypes.AnyAsync(t => t.Id == req.EventTypeId)) return Results.BadRequest(new { message = "Invalid event type." }); var e = new RaceEvent { Name = req.Name.Trim(), Description = req.Description, EventDate = req.EventDate, Location = req.Location.Trim(), DistanceKm = req.DistanceKm, EventTypeId = req.EventTypeId, OrganiserId = ctx.Session.GetInt32("UserId")!.Value }; db.Events.Add(e); await db.SaveChangesAsync(); return Results.Created($"/api/events/{e.Id}", e); }).WithTags("Events");
app.MapPut("/api/events/{id:int}", async (int id, HttpContext ctx, EventRequest req, RaceDayDbContext db) => { if (!Role(ctx, "Organiser")) return Denied(ctx); var e = await db.Events.FindAsync(id); if (e is null) return Results.NotFound(); if (e.OrganiserId != ctx.Session.GetInt32("UserId")) return Results.Forbid(); e.Name = req.Name; e.Description = req.Description; e.EventDate = req.EventDate; e.Location = req.Location; e.DistanceKm = req.DistanceKm; e.EventTypeId = req.EventTypeId; await db.SaveChangesAsync(); return Results.Ok(e); }).WithTags("Events");
app.MapDelete("/api/events/{id:int}", async (int id, HttpContext ctx, RaceDayDbContext db) => { if (!Role(ctx, "Organiser")) return Denied(ctx); var e = await db.Events.FindAsync(id); if (e is null) return Results.NotFound(); if (e.OrganiserId != ctx.Session.GetInt32("UserId")) return Results.Forbid(); db.Events.Remove(e); await db.SaveChangesAsync(); return Results.NoContent(); }).WithTags("Events");
app.MapGet("/api/event-types", async (RaceDayDbContext db) => Results.Ok(await db.EventTypes.OrderBy(x => x.Name).ToListAsync())).WithTags("Event types");
app.MapGet("/api/categories", async (int? eventId, RaceDayDbContext db) => { var q = db.Categories.AsQueryable(); if (eventId.HasValue) q = q.Where(c => c.RaceEventId == eventId.Value); return Results.Ok(await q.ToListAsync()); }).WithTags("Categories");
app.MapPost("/api/categories", async (HttpContext ctx, CategoryRequest req, RaceDayDbContext db) => { if (!Role(ctx, "Organiser")) return Denied(ctx); if (string.IsNullOrWhiteSpace(req.Name)) return Results.BadRequest(new { message = "Category name is required." }); var e = await db.Events.FindAsync(req.RaceEventId); if (e is null) return Results.NotFound(new { message = "Event not found." }); if (e.OrganiserId != ctx.Session.GetInt32("UserId")) return Results.Forbid(); var c = new Category { Name = req.Name.Trim(), Description = req.Description, RaceEventId = req.RaceEventId }; db.Categories.Add(c); await db.SaveChangesAsync(); return Results.Created($"/api/categories/{c.Id}", new {c.Id, c.Name, c.Description, c.RaceEventId}); }).WithTags("Categories");
app.MapPut("/api/categories/{id:int}", async (int id, HttpContext ctx, CategoryRequest req, RaceDayDbContext db) => { if (!Role(ctx, "Organiser")) return Denied(ctx); var c = await db.Categories.Include(x => x.RaceEvent).SingleOrDefaultAsync(x => x.Id == id); if (c is null) return Results.NotFound(); if (c.RaceEvent!.OrganiserId != ctx.Session.GetInt32("UserId")) return Results.Forbid(); c.Name = req.Name; c.Description = req.Description; await db.SaveChangesAsync(); return Results.Ok(c); }).WithTags("Categories");
app.MapDelete("/api/categories/{id:int}", async (int id, HttpContext ctx, RaceDayDbContext db) => { if (!Role(ctx, "Organiser")) return Denied(ctx); var c = await db.Categories.Include(x => x.RaceEvent).SingleOrDefaultAsync(x => x.Id == id); if (c is null) return Results.NotFound(); if (c.RaceEvent!.OrganiserId != ctx.Session.GetInt32("UserId")) return Results.Forbid(); db.Categories.Remove(c); await db.SaveChangesAsync(); return Results.NoContent(); }).WithTags("Categories");
app.MapPost("/api/enrolments", async (HttpContext ctx, EnrolRequest req, RaceDayDbContext db) => { if (!Role(ctx, "Participant")) return Denied(ctx); var uid = ctx.Session.GetInt32("UserId")!.Value; if (!await db.Events.AnyAsync(e => e.Id == req.RaceEventId) || !await db.Categories.AnyAsync(c => c.Id == req.CategoryId && c.RaceEventId == req.RaceEventId)) return Results.BadRequest(new { message = "Event/category combination is invalid." }); if (await db.Enrolments.AnyAsync(x => x.ParticipantId == uid && x.RaceEventId == req.RaceEventId)) return Results.Conflict(new { message = "Already enrolled in this event." }); var en = new Enrolment { ParticipantId = uid, RaceEventId = req.RaceEventId, CategoryId = req.CategoryId }; db.Enrolments.Add(en); await db.SaveChangesAsync(); return Results.Created($"/api/enrolments/{en.Id}", en); }).WithTags("Enrolments");
app.MapGet("/api/enrolments/mine", async (HttpContext ctx, RaceDayDbContext db) => { if (!Role(ctx, "Participant")) return Denied(ctx); var uid = ctx.Session.GetInt32("UserId")!.Value; return Results.Ok(await db.Enrolments.Include(x => x.RaceEvent).Include(x => x.Category).Where(x => x.ParticipantId == uid).Select(x => new { x.Id, x.Status, x.EnrolledUtc, Event = x.RaceEvent!.Name, Category = x.Category!.Name }).ToListAsync()); }).WithTags("Enrolments");
app.MapGet("/api/events/{id:int}/enrolments", async (int id, HttpContext ctx, RaceDayDbContext db) => { if (!Role(ctx, "Organiser")) return Denied(ctx); var e = await db.Events.FindAsync(id); if (e is null) return Results.NotFound(); if (e.OrganiserId != ctx.Session.GetInt32("UserId")) return Results.Forbid(); return Results.Ok(await db.Enrolments.Include(x => x.Participant).Include(x => x.Category).Where(x => x.RaceEventId == id).Select(x => new { x.Id, x.Status, Participant = x.Participant!.FullName, Email = x.Participant!.Email, Category = x.Category!.Name }).ToListAsync()); }).WithTags("Enrolments");
app.MapPost("/api/results", async (HttpContext ctx, ResultRequest req, RaceDayDbContext db) => { if (!Role(ctx, "Organiser")) return Denied(ctx); if (req.Position < 1 || req.FinishTime < TimeSpan.Zero) return Results.BadRequest(new { message = "Position must be positive and finish time cannot be negative." }); var en = await db.Enrolments.Include(x => x.RaceEvent).SingleOrDefaultAsync(x => x.Id == req.EnrolmentId); if (en is null) return Results.NotFound(); if (en.RaceEvent!.OrganiserId != ctx.Session.GetInt32("UserId")) return Results.Forbid(); if (await db.Results.AnyAsync(r => r.EnrolmentId == req.EnrolmentId)) return Results.Conflict(new { message = "Result already recorded." }); var r = new RaceResult { EnrolmentId = req.EnrolmentId, FinishTime = req.FinishTime, Position = req.Position }; db.Results.Add(r); await db.SaveChangesAsync(); return Results.Created($"/api/results/{r.Id}", r); }).WithTags("Results");
app.MapGet("/api/results/mine", async (HttpContext ctx, RaceDayDbContext db) => { if (!Role(ctx, "Participant")) return Denied(ctx); var uid = ctx.Session.GetInt32("UserId")!.Value; return Results.Ok(await db.Results.Include(r => r.Enrolment).ThenInclude(e => e!.RaceEvent).Include(r => r.Enrolment).ThenInclude(e => e!.Participant).Where(r => r.Enrolment!.ParticipantId == uid).Select(r => new { r.Id, Event = r.Enrolment!.RaceEvent!.Name, r.FinishTime, r.Position }).ToListAsync()); }).WithTags("Results");
app.MapGet("/api/events/{id:int}/results", async (int id, HttpContext ctx, RaceDayDbContext db) => { if (!Role(ctx, "Organiser")) return Denied(ctx); var e = await db.Events.FindAsync(id); if (e is null) return Results.NotFound(); if (e.OrganiserId != ctx.Session.GetInt32("UserId")) return Results.Forbid(); return Results.Ok(await db.Results.Include(r => r.Enrolment).ThenInclude(en => en!.Participant).Where(r => r.Enrolment!.RaceEventId == id).OrderBy(r => r.Position).Select(r => new { r.Position, r.FinishTime, Participant = r.Enrolment!.Participant!.FullName }).ToListAsync()); }).WithTags("Results");
app.Run();

static bool Role(HttpContext ctx, string role) => ctx.Session.GetInt32("UserId") is not null && ctx.Session.GetString("Role") == role;
static IResult Denied(HttpContext ctx) => ctx.Session.GetInt32("UserId") is null ? Results.Unauthorized() : Results.Json(new { message = "Your role is not permitted to access this endpoint." }, statusCode: StatusCodes.Status403Forbidden);
public sealed record UserUpdate(string FullName, string? Phone);

